import React, { useState, useEffect } from 'react';
import { supabaseService } from '../../../services/supabaseService';
import { useToast } from '../../../contexts/ToastContext';
import Icon from '../../../components/AppIcon';
import Button from '../../../components/ui/Button';
import Modal from '../../../components/ui/Modal';
import { cn } from '../../../utils/cn';

const CourseAuthoringStudio = ({ instructorId }) => {
    const { addToast } = useToast();
    const [drafts, setDrafts] = useState([]);
    const [isLoading, setIsLoading] = useState(true);
    const [activeDraft, setActiveDraft] = useState(null);
    const [isSaving, setIsSaving] = useState(false);

    useEffect(() => {
        fetchDrafts();
    }, [instructorId]);

    const fetchDrafts = async () => {
        if (!instructorId) return; // Prevent UUID syntax error if ID is missing
        setIsLoading(true);
        try {
            const data = await supabaseService.getInstructorDrafts(instructorId);
            setDrafts(data || []);
        } catch (error) {
            console.error('Failed to fetch course drafts:', error);
            addToast('Failed to load your course studio.', 'error');
        } finally {
            setIsLoading(false);
        }
    };

    const handleCreateNewDraft = () => {
        setActiveDraft({
            title: '',
            description: '',
            thumbnail_url: '',
            price: 0,
            modules: [],
            status: 'draft',
            instructor_id: instructorId
        });
    };

    const handleSaveDraft = async () => {
        if (!activeDraft.title) {
            addToast('Please provide a course title.', 'warning');
            return;
        }
        
        setIsSaving(true);
        try {
            const saved = await supabaseService.saveCourseDraft(activeDraft);
            setActiveDraft(saved);
            addToast('Draft saved securely.', 'success');
            fetchDrafts();
        } catch (error) {
            console.error('Save failed:', error);
            addToast('Failed to save draft.', 'error');
        } finally {
            setIsSaving(false);
        }
    };

    const handleSubmitForReview = async () => {
        if (!activeDraft.id) {
            addToast('Please save the draft first.', 'warning');
            return;
        }
        if (activeDraft.modules.length === 0) {
            addToast('You must add at least one module before submitting.', 'warning');
            return;
        }

        try {
            await supabaseService.submitDraftForReview(activeDraft.id);
            addToast('Course submitted! Administrators will review it shortly.', 'success');
            setActiveDraft(null);
            fetchDrafts();
        } catch (error) {
            addToast('Submission failed.', 'error');
        }
    };

    const handleDeleteDraft = async (id) => {
        if (!window.confirm('Are you sure you want to permanently delete this draft?')) return;
        try {
            await supabaseService.deleteCourseDraft(id);
            addToast('Draft deleted.', 'info');
            fetchDrafts();
            if (activeDraft?.id === id) setActiveDraft(null);
        } catch (error) {
            addToast('Failed to delete draft.', 'error');
        }
    };

    const addModule = () => {
        setActiveDraft({
            ...activeDraft,
            modules: [
                ...activeDraft.modules,
                { id: Date.now().toString(), title: '', lessons: [] }
            ]
        });
    };

    const updateModuleTitle = (index, title) => {
        const newModules = [...activeDraft.modules];
        newModules[index].title = title;
        setActiveDraft({ ...activeDraft, modules: newModules });
    };

    const addLesson = (moduleIndex) => {
        const newModules = [...activeDraft.modules];
        newModules[moduleIndex].lessons.push({
            id: Date.now().toString(),
            title: '',
            type: 'video', // 'video', 'text', 'assignment'
            content: '', // Video URL or text content
            duration: '10 min'
        });
        setActiveDraft({ ...activeDraft, modules: newModules });
    };

    const updateLesson = (moduleIndex, lessonIndex, key, value) => {
        const newModules = [...activeDraft.modules];
        newModules[moduleIndex].lessons[lessonIndex][key] = value;
        setActiveDraft({ ...activeDraft, modules: newModules });
    };

    const removeLesson = (moduleIndex, lessonIndex) => {
        const newModules = [...activeDraft.modules];
        newModules[moduleIndex].lessons.splice(lessonIndex, 1);
        setActiveDraft({ ...activeDraft, modules: newModules });
    };

    // If an active draft is selected, show the Builder Interface
    if (activeDraft) {
        return (
            <div className="space-y-6 animate-in fade-in zoom-in-95 duration-300">
                <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 bg-card p-6 rounded-3xl border border-border sticky top-20 z-10 shadow-sm">
                    <div className="flex items-center gap-4 w-full md:w-auto">
                        <Button 
                            variant="ghost" 
                            size="sm"
                            className="w-10 h-10 rounded-full bg-muted"
                            onClick={() => setActiveDraft(null)}
                        >
                            <Icon name="ArrowLeft" size={20} />
                        </Button>
                        <div>
                            <h3 className="text-xl font-black italic">{activeDraft.title || 'Untitled Course'}</h3>
                            <div className="flex items-center gap-2 text-[10px] uppercase font-bold tracking-widest text-muted-foreground">
                                <span className={cn(
                                    "w-2 h-2 rounded-full",
                                    activeDraft.status === 'draft' ? "bg-yellow-500" : "bg-brand-blue"
                                )} />
                                {activeDraft.status.replace('_', ' ')}
                            </div>
                        </div>
                    </div>
                    <div className="flex flex-wrap md:flex-nowrap items-center gap-3 w-full md:w-auto">
                        <Button 
                            variant="outline" 
                            className="rounded-xl font-bold"
                            onClick={handleSaveDraft}
                            disabled={isSaving || activeDraft.status === 'pending_review'}
                        >
                            {isSaving ? 'SAVING...' : 'SAVE DRAFT'}
                        </Button>
                        <Button 
                            variant="default" 
                            className="rounded-xl font-black italic bg-success text-white hover:bg-success/80 flex-1 md:flex-none"
                            onClick={handleSubmitForReview}
                            disabled={activeDraft.status === 'pending_review'}
                        >
                            <Icon name="Send" size={16} className="mr-2" /> SUBMIT TO ADMIN
                        </Button>
                    </div>
                </div>

                <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
                    {/* Course Metadata */}
                    <div className="lg:col-span-1 space-y-6">
                        <div className="bg-card p-6 rounded-3xl border border-border">
                            <h4 className="font-black italic mb-4 text-primary">Course Details</h4>
                            <div className="space-y-4">
                                <div className="space-y-2">
                                    <label className="text-[10px] font-black uppercase tracking-widest text-muted-foreground ml-1">Course Title</label>
                                    <input 
                                        type="text" 
                                        className="w-full h-12 bg-muted border border-border rounded-xl px-4 font-bold focus:ring-2 focus:ring-primary outline-none"
                                        value={activeDraft.title}
                                        onChange={e => setActiveDraft({...activeDraft, title: e.target.value})}
                                        disabled={activeDraft.status === 'pending_review'}
                                    />
                                </div>
                                <div className="space-y-2">
                                    <label className="text-[10px] font-black uppercase tracking-widest text-muted-foreground ml-1">Description</label>
                                    <textarea 
                                        className="w-full bg-muted border border-border rounded-xl p-4 font-medium min-h-[120px] focus:ring-2 focus:ring-primary outline-none"
                                        value={activeDraft.description}
                                        onChange={e => setActiveDraft({...activeDraft, description: e.target.value})}
                                        disabled={activeDraft.status === 'pending_review'}
                                    />
                                </div>
                                <div className="space-y-2">
                                    <label className="text-[10px] font-black uppercase tracking-widest text-muted-foreground ml-1">Thumbnail URL</label>
                                    <input 
                                        type="text" 
                                        placeholder="https://..."
                                        className="w-full h-12 bg-muted border border-border rounded-xl px-4 font-bold focus:ring-2 focus:ring-primary outline-none"
                                        value={activeDraft.thumbnail_url}
                                        onChange={e => setActiveDraft({...activeDraft, thumbnail_url: e.target.value})}
                                        disabled={activeDraft.status === 'pending_review'}
                                    />
                                </div>
                                <div className="space-y-4 pt-4 border-t border-border">
                                    <div className="flex items-center justify-between mb-2">
                                        <label className="text-[10px] font-black uppercase tracking-widest text-primary italic">Fair-Market Protocol</label>
                                        <div className="group relative">
                                            <Icon name="Info" size={14} className="text-muted-foreground cursor-help" />
                                            <div className="absolute bottom-full right-0 mb-2 w-48 p-3 bg-slate-900 text-[9px] text-white rounded-xl opacity-0 group-hover:opacity-100 transition-opacity pointer-events-none z-50 shadow-2xl border border-white/10 font-medium leading-relaxed">
                                                Higher Fairness Scores increase your course's ranking in the Global Marketplace and lower your platform fee.
                                            </div>
                                        </div>
                                    </div>

                                    <div className="space-y-2">
                                        <label className="text-[10px] font-black uppercase tracking-widest text-muted-foreground ml-1">Price (₦)</label>
                                        <div className="relative">
                                            <span className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400 font-bold">₦</span>
                                            <input 
                                                type="number" 
                                                className="w-full h-12 bg-muted border border-border rounded-xl px-4 pl-8 font-bold focus:ring-2 focus:ring-primary outline-none"
                                                value={activeDraft.price}
                                                onChange={e => setActiveDraft({...activeDraft, price: parseFloat(e.target.value)})}
                                                disabled={activeDraft.status === 'pending_review'}
                                            />
                                        </div>
                                    </div>

                                    {/* FAIRNESS METER */}
                                    <div className="p-5 bg-muted/50 rounded-2xl border border-border space-y-4">
                                        <div className="flex items-center justify-between">
                                            <span className="text-[9px] font-black uppercase tracking-widest text-muted-foreground">LUC Fairness Score</span>
                                            <span className={cn(
                                                "text-[9px] font-black uppercase tracking-widest",
                                                activeDraft.price <= 10000 ? "text-success" : (activeDraft.price <= 30000 ? "text-primary" : "text-amber-500")
                                            )}>
                                                {activeDraft.price <= 10000 ? '100/100' : (activeDraft.price <= 30000 ? '85/100' : (activeDraft.price <= 50000 ? '60/100' : '40/100'))}
                                            </span>
                                        </div>
                                        <div className="w-full h-1.5 bg-muted rounded-full overflow-hidden">
                                            <div 
                                                className="h-full bg-primary transition-all duration-700" 
                                                style={{ width: `${activeDraft.price <= 10000 ? 100 : (activeDraft.price <= 30000 ? 85 : (activeDraft.price <= 50000 ? 60 : 40))}%` }} 
                                            />
                                        </div>
                                        <div className="flex items-center justify-between text-[8px] font-bold uppercase tracking-tighter">
                                            <span className="text-muted-foreground">Platform Fee</span>
                                            <span className="text-primary">{activeDraft.price <= 10000 ? '5%' : (activeDraft.price <= 30000 ? '10%' : '20%')}</span>
                                        </div>
                                        {activeDraft.price > 50000 && (
                                            <div className="pt-2 border-t border-border">
                                                <p className="text-[8px] font-black uppercase tracking-widest text-amber-500 leading-tight">
                                                    Elite Tier: Requires 10% Scholarship Offset
                                                </p>
                                            </div>
                                        )}
                                    </div>
                                </div>
                            </div>
                        </div>
                    </div>

                    {/* Curriculum Builder */}
                    <div className="lg:col-span-2 space-y-6">
                        <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 mb-4">
                            <h4 className="text-2xl font-black italic text-primary">Curriculum</h4>
                            <Button 
                                variant="outline" 
                                size="sm" 
                                className="rounded-xl border-dashed w-full sm:w-auto"
                                onClick={addModule}
                                disabled={activeDraft.status === 'pending_review'}
                            >
                                <Icon name="Plus" size={16} className="mr-2" /> ADD MODULE
                            </Button>
                        </div>

                        {activeDraft.modules.length === 0 ? (
                            <div className="py-20 border-2 border-dashed border-border rounded-[2.5rem] text-center">
                                <Icon name="Layers" size={48} className="mx-auto text-muted-foreground opacity-20 mb-4" />
                                <p className="text-muted-foreground font-medium italic">Start building your curriculum by adding a module.</p>
                            </div>
                        ) : (
                            <div className="space-y-6">
                                {activeDraft.modules.map((module, mIndex) => (
                                    <div key={module.id} className="bg-card border border-border rounded-[2rem] p-6 shadow-sm">
                                        <div className="flex items-center gap-4 mb-6">
                                            <div className="w-8 h-8 rounded-full bg-primary/10 flex items-center justify-center text-primary font-black">
                                                {mIndex + 1}
                                            </div>
                                            <input 
                                                type="text" 
                                                placeholder="Module Title (e.g. Introduction)"
                                                className="flex-1 bg-transparent border-b border-border text-lg font-black italic focus:border-primary outline-none pb-1"
                                                value={module.title}
                                                onChange={(e) => updateModuleTitle(mIndex, e.target.value)}
                                                disabled={activeDraft.status === 'pending_review'}
                                            />
                                        </div>

                                        <div className="space-y-3 pl-12 border-l-2 border-muted ml-4 relative">
                                            {module.lessons.map((lesson, lIndex) => (
                                                <div key={lesson.id} className="bg-muted/30 border border-border rounded-2xl p-4 relative group">
                                                    <div className="absolute -left-[53px] top-1/2 -translate-y-1/2 w-8 border-t-2 border-muted" />
                                                    
                                                    <div className="flex items-start justify-between gap-4">
                                                        <div className="w-8 h-8 rounded-lg bg-primary/10 flex items-center justify-center text-primary shrink-0 mt-1">
                                                            <Icon name={lesson.type === 'video' ? 'Video' : (lesson.type === 'text' ? 'FileText' : 'CheckSquare')} size={16} />
                                                        </div>
                                                        <div className="flex-1 space-y-3">
                                                            <div className="flex flex-col sm:flex-row sm:items-center gap-3 w-full">
                                                                <select 
                                                                    className="bg-background border border-border rounded-lg px-2 py-2 text-xs font-bold uppercase outline-none w-full sm:w-auto"
                                                                    value={lesson.type}
                                                                    onChange={(e) => updateLesson(mIndex, lIndex, 'type', e.target.value)}
                                                                    disabled={activeDraft.status === 'pending_review'}
                                                                >
                                                                    <option value="video">Video</option>
                                                                    <option value="text">Text</option>
                                                                    <option value="assignment">Assignment</option>
                                                                </select>
                                                                <input 
                                                                    type="text" 
                                                                    placeholder="Lesson Title"
                                                                    className="w-full bg-transparent border-b border-border sm:border-none pb-1 sm:pb-0 font-bold outline-none"
                                                                    value={lesson.title}
                                                                    onChange={(e) => updateLesson(mIndex, lIndex, 'title', e.target.value)}
                                                                    disabled={activeDraft.status === 'pending_review'}
                                                                />
                                                            </div>
                                                            <input 
                                                                type="text" 
                                                                placeholder={lesson.type === 'video' ? "Video URL (YouTube/Vimeo)" : "Content or Prompt"}
                                                                className="w-full text-sm bg-background border border-border rounded-lg px-3 py-2 outline-none focus:border-primary"
                                                                value={lesson.content}
                                                                onChange={(e) => updateLesson(mIndex, lIndex, 'content', e.target.value)}
                                                                disabled={activeDraft.status === 'pending_review'}
                                                            />
                                                        </div>
                                                        {activeDraft.status !== 'pending_review' && (
                                                            <button 
                                                                onClick={() => removeLesson(mIndex, lIndex)}
                                                                className="p-2 text-muted-foreground hover:text-destructive transition-colors opacity-100 sm:opacity-0 group-hover:opacity-100"
                                                            >
                                                                <Icon name="Trash2" size={16} />
                                                            </button>
                                                        )}
                                                    </div>
                                                </div>
                                            ))}
                                            
                                            {activeDraft.status !== 'pending_review' && (
                                                <button 
                                                    onClick={() => addLesson(mIndex)}
                                                    className="flex items-center gap-2 text-xs font-bold text-muted-foreground hover:text-primary transition-colors py-2"
                                                >
                                                    <Icon name="PlusCircle" size={14} /> ADD LESSON
                                                </button>
                                            )}
                                        </div>
                                    </div>
                                ))}
                            </div>
                        )}
                    </div>
                </div>
            </div>
        );
    }

    // Default Overview View
    return (
        <div className="space-y-8 animate-in fade-in duration-500">
            {/* Header section */}
            <div className="flex flex-col md:flex-row md:items-center justify-between gap-6">
                <div>
                    <h3 className="text-2xl font-black text-primary italic">Authoring Studio</h3>
                    <p className="text-sm text-muted-foreground">Draft your courses and submit them for approval.</p>
                </div>
                
                <Button 
                    variant="default" 
                    iconName="Plus" 
                    onClick={handleCreateNewDraft}
                    className="font-black italic h-12 px-8 rounded-2xl shadow-xl shadow-primary/10"
                >
                    CREATE NEW COURSE
                </Button>
            </div>

            {/* Drafts Grid */}
            {isLoading ? (
                <div className="py-20 flex flex-col items-center justify-center">
                    <div className="w-12 h-12 border-4 border-secondary border-t-transparent rounded-full animate-spin" />
                </div>
            ) : drafts.length > 0 ? (
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                    {drafts.map((draft) => (
                        <div key={draft.id} className="group flex flex-col bg-card border border-border rounded-[2.5rem] overflow-hidden hover:shadow-xl transition-all">
                            <div className="h-32 bg-muted relative">
                                {draft.thumbnail_url ? (
                                    <img src={draft.thumbnail_url} alt="Cover" className="w-full h-full object-cover" />
                                ) : (
                                    <div className="w-full h-full flex items-center justify-center text-muted-foreground/30">
                                        <Icon name="Image" size={40} />
                                    </div>
                                )}
                                <div className="absolute top-4 right-4">
                                    <span className={cn(
                                        "px-3 py-1 rounded-full text-[10px] font-black uppercase tracking-widest shadow-md",
                                        draft.status === 'draft' ? "bg-yellow-500 text-white" : 
                                        (draft.status === 'pending_review' ? "bg-brand-blue text-white" : 
                                        (draft.status === 'approved' ? "bg-success text-white" : "bg-destructive text-white"))
                                    )}>
                                        {draft.status.replace('_', ' ')}
                                    </span>
                                </div>
                            </div>
                            
                            <div className="p-6 flex-1 flex flex-col">
                                <h4 className="text-lg font-black text-foreground italic mb-2 line-clamp-1">{draft.title || 'Untitled Draft'}</h4>
                                <div className="flex items-center gap-4 text-xs text-muted-foreground font-medium mb-6">
                                    <div className="flex items-center gap-1">
                                        <Icon name="Layers" size={14} />
                                        <span>{draft.modules?.length || 0} Modules</span>
                                    </div>
                                    <div className="flex items-center gap-1 text-secondary font-bold">
                                        <Icon name="Tag" size={14} />
                                        <span>₦{draft.price?.toLocaleString()}</span>
                                    </div>
                                </div>
                                
                                <div className="mt-auto flex items-center gap-2">
                                    <Button 
                                        variant="default" 
                                        fullWidth 
                                        size="sm" 
                                        className="rounded-xl font-bold bg-primary text-white hover:bg-primary/90"
                                        onClick={() => setActiveDraft(draft)}
                                    >
                                        {draft.status === 'pending_review' ? 'VIEW READ-ONLY' : 'CONTINUE EDITING'}
                                    </Button>
                                    {draft.status === 'draft' && (
                                        <Button 
                                            variant="outline" 
                                            size="sm" 
                                            className="w-10 h-10 p-0 rounded-xl border-destructive/20 text-destructive hover:bg-destructive hover:text-white flex items-center justify-center transition-colors"
                                            onClick={() => handleDeleteDraft(draft.id)}
                                        >
                                            <Icon name="Trash2" size={16} />
                                        </Button>
                                    )}
                                </div>
                            </div>
                        </div>
                    ))}
                </div>
            ) : (
                <div className="py-20 text-center space-y-4 bg-muted/5 border-4 border-dashed border-border rounded-[3rem]">
                    <Icon name="PenTool" size={64} className="mx-auto text-muted-foreground opacity-20" />
                    <p className="text-sm text-muted-foreground font-medium italic">Your studio is empty. Start drafting your first masterpiece!</p>
                </div>
            )}
        </div>
    );
};

export default CourseAuthoringStudio;
