import React, { useState, useEffect } from 'react';
import { supabaseService } from '../../../services/supabaseService';
import { formatLuc } from '../../../utils/currencyUtils';
import Icon from '../../../components/AppIcon';
import Button from '../../../components/ui/Button';
import { useToast } from '../../../contexts/ToastContext';

const InstructorPromoCodeSection = ({ userId }) => {
    const { addToast } = useToast();
    const [promoCode, setPromoCode] = useState(null);
    const [usages, setUsages] = useState([]);
    const [isLoading, setIsLoading] = useState(true);
    const [isGenerating, setIsGenerating] = useState(false);
    const [copied, setCopied] = useState(false);

    useEffect(() => {
        if (!userId) return;
        loadData();
    }, [userId]);

    const loadData = async () => {
        setIsLoading(true);
        try {
            const [code, usageData] = await Promise.all([
                supabaseService.getInstructorPromoCode(userId),
                supabaseService.getInstructorPromoUsages(userId)
            ]);
            setPromoCode(code);
            setUsages(usageData);
        } catch (err) {
            console.error('Failed to load promo code data:', err);
        } finally {
            setIsLoading(false);
        }
    };

    const copyToClipboard = (text) => {
        navigator.clipboard.writeText(text).then(() => {
            setCopied(true);
            addToast('Copied to clipboard!', 'success');
            setTimeout(() => setCopied(false), 2000);
        });
    };

    const referralLink = promoCode
        ? `${window.location.origin}/academy?promo=${promoCode.code}#tracks`
        : '';

    const totalLucEarned = usages.reduce((sum, u) => sum + (u.luc_credited || 0), 0);

    if (isLoading) {
        return (
            <div className="flex justify-center py-20">
                <div className="w-8 h-8 border-4 border-primary border-t-transparent rounded-full animate-spin" />
            </div>
        );
    }

    if (!promoCode) {
        const handleGenerate = async () => {
            setIsGenerating(true);
            try {
                const profile = await supabaseService.getProfile(userId);
                const name = profile?.full_name || 'Instructor';
                const newCode = await supabaseService.generateInstructorPromoCode(userId, name);
                setPromoCode(newCode);
                addToast(`Promo code generated: ${newCode.code}`, 'success');
            } catch (err) {
                console.error('Promo code generation failed:', err);
                addToast('Failed to generate promo code. Please try again.', 'error');
            } finally {
                setIsGenerating(false);
            }
        };

        return (
            <div className="space-y-6">
                <div>
                    <h2 className="text-2xl font-black italic text-primary">My Promo Code</h2>
                    <p className="text-sm text-muted-foreground mt-1">
                        Share your unique promo code with students to give them 10% off your courses.
                    </p>
                </div>
                <div className="py-20 text-center border border-dashed border-border rounded-2xl">
                    <Icon name="Tag" size={48} className="mx-auto mb-4 text-muted-foreground/30" />
                    <p className="text-muted-foreground font-medium">No promo code assigned yet.</p>
                    <p className="text-xs text-muted-foreground mt-1 mb-6">Generate your instructor promo code to start sharing.</p>
                    <Button
                        onClick={handleGenerate}
                        loading={isGenerating}
                        className="px-6 rounded-xl font-bold"
                    >
                        Generate Code
                    </Button>
                </div>
            </div>
        );
    }

    return (
        <div className="space-y-6">
            <div>
                <h2 className="text-2xl font-black italic text-primary">My Promo Code</h2>
                <p className="text-sm text-muted-foreground mt-1">
                    Share your unique promo code with students to give them 10% off your courses. You earn LUC credits for every use.
                </p>
            </div>

            {/* Promo Code Card */}
            <div className="p-6 sm:p-8 bg-gradient-to-br from-primary/5 via-card to-secondary/5 border border-primary/20 rounded-[2rem] relative overflow-hidden">
                <div className="absolute top-0 right-0 w-64 h-64 bg-primary/10 rounded-full blur-[80px] -translate-y-1/2 translate-x-1/2 pointer-events-none" />
                
                <div className="relative z-10 space-y-6">
                    <div className="flex items-center gap-4">
                        <div className="w-14 h-14 bg-primary/10 rounded-2xl flex items-center justify-center border border-primary/20">
                            <Icon name="Tag" size={28} className="text-primary" />
                        </div>
                        <div>
                            <p className="text-[10px] font-black uppercase tracking-widest text-muted-foreground">Your Instructor Code</p>
                            <p className="text-3xl font-black italic text-primary tracking-wider">{promoCode.code}</p>
                        </div>
                    </div>

                    {/* Stats Row */}
                    <div className="grid grid-cols-2 sm:grid-cols-3 gap-4">
                        <div className="p-4 bg-card border border-border rounded-2xl">
                            <p className="text-2xl font-black text-primary">{promoCode.total_uses}</p>
                            <p className="text-[10px] font-black uppercase tracking-widest text-muted-foreground mt-1">Total Uses</p>
                        </div>
                        <div className="p-4 bg-card border border-border rounded-2xl">
                            <p className="text-2xl font-black text-emerald-600">{formatLuc(totalLucEarned)}</p>
                            <p className="text-[10px] font-black uppercase tracking-widest text-muted-foreground mt-1">LUC Earned</p>
                        </div>
                        <div className="p-4 bg-card border border-border rounded-2xl col-span-2 sm:col-span-1">
                            <p className="text-2xl font-black text-secondary">{promoCode.discount_percent}%</p>
                            <p className="text-[10px] font-black uppercase tracking-widest text-muted-foreground mt-1">Discount Given</p>
                        </div>
                    </div>

                    {/* Referral Link */}
                    <div>
                        <p className="text-[10px] font-black uppercase tracking-widest text-muted-foreground mb-2">Referral Link</p>
                        <div className="flex gap-2">
                            <input
                                type="text"
                                value={referralLink}
                                readOnly
                                className="flex-1 px-4 py-3 bg-muted border border-border rounded-xl text-sm font-medium text-muted-foreground"
                            />
                            <Button
                                onClick={() => copyToClipboard(referralLink)}
                                className="px-6 rounded-xl font-bold shrink-0"
                            >
                                <Icon name={copied ? "Check" : "Copy"} size={16} className="mr-2" />
                                {copied ? 'Copied!' : 'Copy'}
                            </Button>
                        </div>
                    </div>

                    {/* Share Buttons */}
                    <div className="flex gap-3">
                        <Button
                            variant="outline"
                            onClick={() => copyToClipboard(promoCode.code)}
                            className="flex-1 rounded-xl font-bold"
                        >
                            <Icon name="Copy" size={16} className="mr-2" />
                            Copy Code
                        </Button>
                        <Button
                            variant="outline"
                            onClick={() => {
                                const text = `Use my promo code ${promoCode.code} for 10% off courses on LUC Academy! ${referralLink}`;
                                copyToClipboard(text);
                            }}
                            className="flex-1 rounded-xl font-bold"
                        >
                            <Icon name="Share2" size={16} className="mr-2" />
                            Share
                        </Button>
                    </div>
                </div>
            </div>

            {/* Usage History */}
            {usages.length > 0 && (
                <div className="border border-border rounded-2xl overflow-hidden bg-card">
                    <div className="px-6 py-4 border-b border-border bg-muted/50">
                        <h3 className="font-black italic text-primary">Recent Usage</h3>
                    </div>
                    <div className="overflow-x-auto">
                        <table className="w-full text-sm">
                            <thead>
                                <tr className="border-b border-border bg-muted/30">
                                    <th className="text-left px-6 py-3 text-[10px] font-black uppercase tracking-widest text-muted-foreground">Date</th>
                                    <th className="text-left px-6 py-3 text-[10px] font-black uppercase tracking-widest text-muted-foreground">Course</th>
                                    <th className="text-right px-6 py-3 text-[10px] font-black uppercase tracking-widest text-muted-foreground">Discount</th>
                                    <th className="text-right px-6 py-3 text-[10px] font-black uppercase tracking-widest text-muted-foreground">LUC Earned</th>
                                </tr>
                            </thead>
                            <tbody className="divide-y divide-border">
                                {usages.slice(0, 10).map((usage) => (
                                    <tr key={usage.id} className="hover:bg-muted/30 transition-colors">
                                        <td className="px-6 py-3 text-sm font-medium">
                                            {new Date(usage.created_at).toLocaleDateString()}
                                        </td>
                                        <td className="px-6 py-3 text-sm font-medium truncate max-w-[200px]">
                                            {usage.course_id}
                                        </td>
                                        <td className="px-6 py-3 text-right text-sm font-bold text-emerald-600">
                                            -₦{usage.discount_amount?.toLocaleString()}
                                        </td>
                                        <td className="px-6 py-3 text-right text-sm font-bold text-primary">
                                            +{formatLuc(usage.luc_credited)}
                                        </td>
                                    </tr>
                                ))}
                            </tbody>
                        </table>
                    </div>
                </div>
            )}
        </div>
    );
};

export default InstructorPromoCodeSection;
