import React, { useState, useEffect } from 'react';
import { useSelector, useDispatch } from 'react-redux';
import { motion, AnimatePresence } from 'framer-motion';
import Header from '../../components/ui/Header';
import Footer from '../../components/ui/Footer';
import Icon from '../../components/AppIcon';
import Button from '../../components/ui/Button';
import AcademyManagement from '../admin-dashboard/components/AcademyManagement';
import VaultManagement from '../admin-dashboard/components/VaultManagement';
import ScholarshipManagement from '../admin-dashboard/components/ScholarshipManagement';
import AdminPayoutControl from '../profile/components/AdminPayoutControl';
import LiveSessionManagement from '../admin-dashboard/components/LiveSessionManagement';
import CourseAuthoringStudio from '../profile/components/CourseAuthoringStudio';
import OfficeHoursManager from '../profile/components/OfficeHoursManager';
import BroadcastManager from '../profile/components/BroadcastManager';
import AssignmentGrader from '../profile/components/AssignmentGrader';
import CourseWorkRegister from '../admin-dashboard/components/CourseWorkRegister';
import InstructorAnalytics from '../profile/components/InstructorAnalytics';
import InstructorWallet from '../profile/components/InstructorWallet';
import InstructorPromoCodeSection from '../profile/components/InstructorPromoCodeSection';
import MfaSettings from '../profile/components/MfaSettings';
import { supabaseService } from '../../services/supabaseService';
import { updateUserDetails } from '../../store/authSlice';
import { cn } from '../../utils/cn';

const InstructorDashboard = () => {
  const [activeTab, setActiveTab] = useState('overview');
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [mfaVerified, setMfaVerified] = useState(true); // Default true, then checked
  const [checkingMfa, setCheckingMfa] = useState(true);
  const dispatch = useDispatch();
  const { user } = useSelector((state) => state.auth);
  const academyCourses = useSelector((state) => state.content.academy) || [];
  const vaultCourses = useSelector((state) => state.content.vault) || [];

  useEffect(() => {
      const initDashboard = async () => {
          if (!user?.id) return;
          try {
              // 1. Check MFA Status
              const mfaData = await supabaseService.getMfaFactors();
              const activeFactors = mfaData.totp?.filter(f => f.status === 'verified') || [];
              setMfaVerified(activeFactors.length > 0);

              // 2. Refresh Profile Data (ensures gender is available for Sir/Ma greeting)
              const profile = await supabaseService.getProfile(user.id);
              if (profile) {
                  dispatch(updateUserDetails({ gender: profile.gender }));
              }
          } catch (error) {
              console.error("Dashboard initialization failed", error);
              // We don't necessarily want to lock them out if getProfile fails, 
              // but MFA check failure should probably stay conservative.
              if (error.message?.includes('MFA')) setMfaVerified(false);
          } finally {
              setCheckingMfa(false);
          }
      };
      initDashboard();
  }, [user?.id, dispatch]);
  
  // Filter courses where the current user is the instructor
  const instructorCourses = [...academyCourses, ...vaultCourses].filter(c => 
    c && (c.instructor_id === user?.id || c.instructorId === user?.id)
  );

  const navigationGroups = [
    {
      group: 'DASHBOARD',
      tabs: [
        { id: 'overview', label: 'Overview', icon: 'LayoutDashboard' },
        { id: 'analytics', label: 'Student Insights', icon: 'BarChart3' }
      ]
    },
    {
      group: 'TEACHING',
      tabs: [
        { id: 'studio', label: 'Authoring Studio', icon: 'PenTool' },
        { id: 'academy', label: 'My Courses', icon: 'GraduationCap' },
        { id: 'vault', label: 'Growth Vault', icon: 'Archive' },
        { id: 'office-hours', label: 'Office Hours', icon: 'Calendar' },
        { id: 'live-sessions', label: 'Live Sessions', icon: 'Video' },
        { id: 'assignments', label: 'Assignments', icon: 'CheckSquare' },
        { id: 'coursework', label: 'Open Register', icon: 'ClipboardList' },
      ]
    },
    {
      group: 'COMMUNICATION',
      tabs: [
        { id: 'broadcasts', label: 'Broadcasts', icon: 'Megaphone' },
      ]
    },
    {
      group: 'IMPACT & EARNINGS',
      tabs: [
        { id: 'scholarships', label: 'Scholarships', icon: 'Gift' },
        { id: 'promo-code', label: 'My Promo Code', icon: 'Tag' },
        { id: 'wallet', label: 'Instructor Wallet', icon: 'Wallet' },
        { id: 'payouts', label: 'Payouts', icon: 'DollarSign' }
      ]
    }
  ];

  const getGreeting = () => {
    const hour = new Date().getHours();
    if (hour < 12) return 'Good Morning,';
    if (hour < 18) return 'Good Afternoon,';
    return 'Good Evening,';
  };

  const getTitle = () => {
    const gender = user?.gender?.toLowerCase();
    if (gender === 'male' || gender === 'm') return 'Sir';
    if (gender === 'female' || gender === 'f') return 'Ma';
    return user?.name?.split(' ')[0] || 'Instructor';
  };

  const renderTabContent = () => {
    switch(activeTab) {
      case 'overview': return (
        <div className="space-y-8">
            <motion.div 
                initial={{ opacity: 0, y: 20 }}
                animate={{ opacity: 1, y: 0 }}
                className="bg-gradient-to-br from-card via-card to-primary/5 border border-border rounded-[2.5rem] p-8 md:p-12 shadow-2xl relative overflow-hidden group"
            >
                <div className="absolute top-0 right-0 w-96 h-96 bg-primary/10 rounded-full blur-[100px] -translate-y-1/2 translate-x-1/2 pointer-events-none group-hover:bg-primary/20 transition-colors duration-1000" />
                <div className="absolute bottom-0 left-0 w-96 h-96 bg-secondary/10 rounded-full blur-[100px] translate-y-1/2 -translate-x-1/2 pointer-events-none" />
                
                <div className="relative z-10">
                    <div className="w-20 h-20 bg-primary/10 rounded-[2rem] flex items-center justify-center mb-8 text-primary shadow-inner border border-primary/20">
                        <Icon name="Presentation" size={40} />
                    </div>
                    <h2 className="text-4xl md:text-5xl font-black italic tracking-tighter mb-4 uppercase">
                        {getGreeting()} <span className="text-primary">{getTitle()}</span>
                    </h2>
                    <p className="text-muted-foreground max-w-xl text-lg mb-10 leading-relaxed font-medium">
                        Your Instructor Hub is optimized. Monitor your students' progress, manage your curriculum, and track your revenue growth all in one place.
                    </p>
                    
                    <div className="flex flex-wrap gap-4">
                        <button 
                            onClick={() => setActiveTab('studio')}
                            className="px-8 py-4 bg-primary text-primary-foreground font-black italic rounded-2xl shadow-xl shadow-primary/20 hover:scale-105 active:scale-95 transition-all flex items-center gap-3"
                        >
                            <Icon name="PenTool" size={20} />
                            CREATE NEW CONTENT
                        </button>
                        <button 
                            onClick={() => setActiveTab('analytics')}
                            className="px-8 py-4 bg-card text-foreground border border-border font-black italic rounded-2xl hover:bg-muted transition-all flex items-center gap-3"
                        >
                            <Icon name="BarChart3" size={20} />
                            VIEW STUDENT INSIGHTS
                        </button>
                    </div>
                </div>
            </motion.div>

            <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                {[
                    { id: 'academy', label: 'My Courses', desc: 'Manage your published curriculum.', icon: 'GraduationCap', color: 'blue' },
                    { id: 'office-hours', label: 'Office Hours', desc: 'Schedule 1-on-1 mentorship.', icon: 'Calendar', color: 'indigo' },
                    { id: 'wallet', label: 'Earnings', desc: 'Track revenue and payouts.', icon: 'Wallet', color: 'emerald' }
                ].map((item, idx) => (
                    <motion.div 
                        key={item.id}
                        initial={{ opacity: 0, y: 20 }}
                        animate={{ opacity: 1, y: 0 }}
                        transition={{ delay: 0.1 * (idx + 1) }}
                        onClick={() => setActiveTab(item.id)}
                        className="bg-card border border-border rounded-[2rem] p-8 hover:shadow-2xl hover:border-primary/50 transition-all cursor-pointer group relative overflow-hidden"
                    >
                        <div className={cn(
                            "w-14 h-14 rounded-2xl flex items-center justify-center mb-6 group-hover:scale-110 transition-transform duration-500",
                            item.color === 'blue' && "bg-blue-500/10 text-blue-500",
                            item.color === 'indigo' && "bg-indigo-500/10 text-indigo-500",
                            item.color === 'emerald' && "bg-emerald-500/10 text-emerald-500"
                        )}>
                            <Icon name={item.icon} size={28} />
                        </div>
                        <h3 className="font-black italic text-xl mb-2 text-primary uppercase tracking-tight">{item.label}</h3>
                        <p className="text-sm text-muted-foreground font-medium leading-relaxed">{item.desc}</p>
                        
                        <div className="absolute bottom-4 right-4 opacity-0 group-hover:opacity-100 transition-opacity translate-x-2 group-hover:translate-x-0 transition-transform">
                            <Icon name="ArrowRight" size={20} className="text-primary" />
                        </div>
                    </motion.div>
                ))}
            </div>
        </div>
      );
      case 'academy': return <AcademyManagement courses={academyCourses.filter(c => c.instructor_id === user?.id || c.instructorId === user?.id)} />;
      case 'vault': return <VaultManagement lessons={vaultCourses.filter(c => c.instructor_id === user?.id || c.instructorId === user?.id)} />;
      case 'scholarships': return <ScholarshipManagement />;
      case 'payouts': return <AdminPayoutControl />;
      case 'live-sessions': return <LiveSessionManagement />;
      case 'studio': return <CourseAuthoringStudio instructorId={user?.id} />;
      case 'office-hours': return <OfficeHoursManager userId={user?.id} />;
      case 'broadcasts': return <BroadcastManager instructorId={user?.id} courses={instructorCourses} />;
      case 'assignments': return <AssignmentGrader instructorId={user?.id} courses={instructorCourses} />;
      case 'coursework': return <CourseWorkRegister instructorId={user?.id} />;
      case 'analytics': return <InstructorAnalytics userId={user?.id} />;
      case 'wallet': return <InstructorWallet userId={user?.id} />;
      case 'promo-code': return <InstructorPromoCodeSection userId={user?.id} />;
      default: return null;
    }
  };

  if (checkingMfa) {
    return (
        <div className="min-h-screen bg-background flex flex-col items-center justify-center" data-security-clearance="true">
            <Icon name="ShieldCheck" size={48} className="text-primary animate-pulse mb-4" />
            <p className="font-bold tracking-widest uppercase text-muted-foreground">Verifying Security Clearance...</p>
        </div>
    );
  }

  if (!mfaVerified) {
    return (
        <div className="min-h-screen bg-background flex flex-col font-sans selection:bg-primary/30">
            <Header />
            <div className="flex-1 flex items-center justify-center p-4 py-12">
                 <div className="max-w-2xl w-full bg-card border border-destructive/30 rounded-[2.5rem] p-8 md:p-12 shadow-2xl shadow-destructive/10 relative overflow-hidden text-center space-y-8 animate-in zoom-in-95 duration-500">
                     <div className="absolute top-0 right-0 w-64 h-64 bg-destructive/5 rounded-full blur-[80px] -translate-y-1/2 translate-x-1/2 pointer-events-none" />
                     
                     <div className="w-24 h-24 bg-destructive/10 rounded-[2.5rem] flex items-center justify-center mx-auto text-destructive shadow-inner border border-destructive/20 relative z-10">
                         <Icon name="ShieldAlert" size={48} />
                     </div>
                     
                     <div className="relative z-10">
                         <h2 className="text-3xl md:text-4xl font-black italic tracking-tighter uppercase mb-3">Mandatory Security Upgrade</h2>
                         <p className="text-muted-foreground font-medium text-lg max-w-lg mx-auto">
                             As an instructor, you are <strong className="text-foreground">required</strong> to enable Two-Factor Authentication (2FA) before accessing the command center.
                         </p>
                     </div>
                     
                     <div className="text-left bg-background border border-border rounded-2xl p-6 relative z-10 shadow-sm">
                         <MfaSettings onStatusChange={(isActive) => {
                             if (isActive) setMfaVerified(true);
                         }} />
                     </div>

                     <div className="pt-4 border-t border-border relative z-10">
                         <Button variant="ghost" onClick={() => window.location.href = '/'} className="font-bold tracking-widest uppercase text-xs">Return to Home</Button>
                     </div>
                 </div>
            </div>
            <Footer />
        </div>
    );
  }

  return (
    <div className="min-h-screen bg-background flex flex-col font-sans selection:bg-primary/30 overflow-hidden">
      <Header />

      {/* Main Layout Container */}
      <div className="flex-1 flex overflow-hidden">
        
        {/* Mobile Sidebar Overlay */}
        <AnimatePresence>
            {isSidebarOpen && (
            <motion.div 
                initial={{ opacity: 0 }}
                animate={{ opacity: 1 }}
                exit={{ opacity: 0 }}
                className="fixed inset-0 bg-background/80 backdrop-blur-sm z-40 lg:hidden"
                onClick={() => setIsSidebarOpen(false)}
            />
            )}
        </AnimatePresence>

        {/* Sidebar Navigation */}
        <aside className={cn(
            "fixed lg:static top-16 sm:top-20 lg:top-0 left-0 z-50 w-72 bg-card border-r border-border transition-all duration-500 ease-in-out flex flex-col h-[calc(100vh-4rem)] sm:h-[calc(100vh-5rem)] lg:h-[calc(100vh-6rem)] shadow-2xl lg:shadow-none",
            isSidebarOpen ? 'translate-x-0' : '-translate-x-full lg:translate-x-0'
        )}>
          <div className="p-8 relative">
            <h2 className="text-2xl font-black italic tracking-tighter flex items-center gap-3">
              <div className="p-2 bg-primary/10 rounded-lg">
                <Icon name="Presentation" size={20} className="text-primary" />
              </div>
              INSTRUCTOR
            </h2>
            <p className="text-[10px] font-black uppercase tracking-[0.2em] text-muted-foreground mt-2 opacity-60">Elite Teaching Hub</p>
          </div>

          <nav className="flex-1 overflow-y-auto custom-scrollbar px-4 pb-12 space-y-8">
            {navigationGroups.map((group, idx) => (
              <div key={idx} className="space-y-2">
                <h3 className="px-4 text-[9px] font-black uppercase tracking-[0.3em] text-primary/40 mb-3">
                  {group.group}
                </h3>
                <div className="space-y-1">
                    {group.tabs.map((tab) => (
                    <button
                        key={tab.id}
                        onClick={() => {
                        setActiveTab(tab.id);
                        setIsSidebarOpen(false);
                        }}
                        className={cn(
                            "w-full flex items-center gap-3 px-4 py-3 rounded-2xl text-xs font-black italic transition-all duration-300 relative group",
                            activeTab === tab.id 
                                ? 'text-primary' 
                                : 'text-muted-foreground hover:text-foreground hover:bg-muted/50'
                        )}
                    >
                        {activeTab === tab.id && (
                            <motion.div 
                                layoutId="activeTab"
                                className="absolute inset-0 bg-primary/5 border border-primary/20 rounded-2xl -z-10"
                                transition={{ type: "spring", bounce: 0.2, duration: 0.6 }}
                            />
                        )}
                        <Icon 
                            name={tab.icon} 
                            size={18} 
                            className={cn(
                                "transition-colors",
                                activeTab === tab.id ? "text-primary" : "group-hover:text-primary"
                            )} 
                        />
                        <span className="uppercase tracking-widest">{tab.label}</span>
                    </button>
                    ))}
                </div>
              </div>
            ))}
          </nav>

          <div className="p-4 border-t border-border">
            <div className="p-4 bg-muted/30 rounded-2xl flex items-center gap-3">
                <div className="w-10 h-10 bg-primary/20 rounded-full flex items-center justify-center font-black italic text-primary">
                    {user?.name?.charAt(0) || 'I'}
                </div>
                <div className="min-w-0">
                    <p className="text-[10px] font-black italic truncate">{user?.name || 'Instructor'}</p>
                    <p className="text-[8px] text-muted-foreground font-bold uppercase truncate">Verified Faculty</p>
                </div>
            </div>
          </div>
        </aside>

        {/* Main Content Area */}
        <main className="flex-1 overflow-y-auto custom-scrollbar h-[calc(100vh-4rem)] sm:h-[calc(100vh-5rem)] lg:h-[calc(100vh-6rem)] bg-muted/5 relative">
          
          {/* Mobile Sidebar Toggle - Dynamic Handle */}
          <motion.button 
            initial={{ opacity: 0 }}
            animate={{ 
                opacity: 1,
                x: isSidebarOpen ? 288 : 0 // 288px is the width of the 72w sidebar
            }}
            transition={{ type: "spring", damping: 20, stiffness: 100 }}
            whileHover={{ scale: 1.1 }}
            whileTap={{ scale: 0.9 }}
            className="lg:hidden fixed left-0 top-[45%] z-[60] p-3 pr-4 bg-primary text-white rounded-r-3xl shadow-2xl shadow-primary/40 flex items-center justify-center border-y border-r border-white/10 transition-colors"
            onClick={() => setIsSidebarOpen(!isSidebarOpen)}
          >
            <Icon name={isSidebarOpen ? "ChevronLeft" : "ChevronRight"} size={24} />
          </motion.button>

          <div className="max-w-7xl mx-auto p-4 sm:p-8 lg:p-12">
            
            {/* Header Area */}
            <div className="mb-12">
              <div className="flex flex-col gap-3">
                <div className="flex items-center gap-3">
                    <div className="h-1 w-12 bg-primary rounded-full" />
                    <span className="text-[10px] font-black uppercase tracking-[0.4em] text-primary">LUC Control Panel</span>
                </div>
                <h1 className="text-4xl md:text-5xl font-black italic tracking-tighter uppercase leading-none">
                  {activeTab.replace('-', ' ')}
                </h1>
                <p className="text-muted-foreground font-bold italic text-sm md:text-base max-w-2xl opacity-70">
                  {activeTab === 'overview' && `Command center for ${user?.name || 'Instructor'}. Synchronize your impact.`}
                  {activeTab === 'academy' && "High-performance curriculum management & enrollment analytics."}
                  {activeTab === 'vault' && "LUC Growth Vault premium module distribution center."}
                  {activeTab === 'scholarships' && "Monitor the progress and returns of your student sponsorships."}
                  {activeTab === 'payouts' && "Capital management and distribution controls."}
                  {activeTab === 'live-sessions' && "Synchronized live mentorship and brainstorming broadcast."}
                  {activeTab === 'studio' && "Advanced curriculum architecture and content production."}
                </p>
              </div>
            </div>

            {/* Content Switcher */}
            <div className="min-h-[60vh] relative">
                <AnimatePresence mode="wait">
                    <motion.div
                        key={activeTab}
                        initial={{ opacity: 0, y: 10 }}
                        animate={{ opacity: 1, y: 0 }}
                        exit={{ opacity: 0, y: -10 }}
                        transition={{ duration: 0.3, ease: "easeOut" }}
                    >
                        {renderTabContent()}
                    </motion.div>
                </AnimatePresence>
            </div>
            
          </div>
          <Footer />
        </main>
      </div>
    </div>
  );
};

export default InstructorDashboard;
